  justify-content: center;
  flex-wrap: wrap;
}
.game-over-box .message {
  font-size: 0.85rem;
  margin-bottom: 8px;
  min-height: 1.2em;
}
.game-over-box .message.success { color: #2ecc71; }
.game-over-box .message.error { color: #e74c3c; }

/* ===== Leaderboard View ===== */
.leaderboard-view {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,0.85);
  z-index: 20;
  display: flex;
  justify-content: center;
  align-items: center;
}
.leaderboard-box {
  background: linear-gradient(145deg, #1a1a2e, #16213e);
  border: 1px solid #2a2a4a;
  border-radius: 16px;
  padding: 24px 32px;
  max-width: 400px;
  width: 90%;
  max-height: 80vh;
  overflow-y: auto;
}
.leaderboard-box h2 {
  text-align: center;
  color: #ffd700;
  margin-bottom: 16px;
  font-size: 1.3rem;
}
