  width: 100%;
  border-collapse: collapse;
}
.leaderboard-box th {
  color: #888;
  font-size: 0.8rem;
  text-transform: uppercase;
  padding: 6px 4px;
  border-bottom: 1px solid #2a2a4a;
}
.leaderboard-box td {
  padding: 8px 4px;
  text-align: center;
  border-bottom: 1px solid #1a1a2e;
}
.leaderboard-box .rank { width: 32px; color: #888; }
.leaderboard-box .nickname { text-align: left; }
.leaderboard-box .score { font-weight: 600; color: #ffd700; }
.leaderboard-box .date { color: #666; font-size: 0.78rem; }
.leaderboard-box .close-btn {
  display: block;
  margin: 16px auto 0;
}
.leaderboard-box .empty {
  text-align: center;
  color: #666;
  padding: 20px 0;
}
.leaderboard-box .error {
  text-align: center;
  color: #e74c3c;
  padding: 12px 0;
}
"}

