// Domain constants
export const MAX_NICKNAME_LENGTH = 16;
export const MIN_NICKNAME_LENGTH = 1;
export const LEADERBOARD_TOP_N = 10;
export const LS_PREFIX = 'arcade.';
export const LS_SCORES_KEY = (gameId) => `${LS_PREFIX}scores.${gameId}`;
export const LS_BEST_KEY = (gameId) => `${LS_PREFIX}best.${gameId}`;

// Regex: printable characters, no control chars
export const NICKNAME_RE = /^[\x20-\x7E]+$/;

/**
 * @typedef {Object} ScoreEntry
 * @property {string} gameId
 * @property {string} nickname
 * @property {number} score
 * @property {string} playedAt - ISO 8601
 */

/** Create a validated score entry. */
export function createScoreEntry(gameId, nickname, score) {
  return Object.freeze({
    gameId: String(gameId),
    nickname: String(nickname),
    score: Math.floor(score),
    playedAt: new Date().toISOString(),
  });
}

/**
 * @interface IReadableLeaderboard
 * @method getTopScores(gameId, limit) → ScoreEntry[]
 * @method getBestScore(gameId) → number | null
 */

/**
 * @interface IWritableLeaderboard
 * @method saveScore(entry) → void
 */

// Pure documentation — no real class needed in JS, but we use these names
// as the dependency-inversion contract.

import { NICKNAME_RE, MAX_NICKNAME_LENGTH, MIN_NICKNAME_LENGTH } from '../domain/constants.js';

/**
 * Validate and normalize a nickname.
 * @param {string} raw
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function validateNickname(raw) {
  if (typeof raw !== 'string') {
    return { ok: false, error: 'Никнейм должен быть строкой.' };
  }
  let value = raw.trim().replace(/\s+/g, ' ');
  if (value.length < MIN_NICKNAME_LENGTH) {
    return { ok: false, error: 'Никнейм не может быть пустым.' };
  }
  if (value.length > MAX_NICKNAME_LENGTH) {
    return { ok: false, error: `Никнейм не длиннее ${MAX_NICKNAME_LENGTH} символов.` };
  }
  if (!NICKNAME_RE.test(value)) {
    return { ok: false, error: 'Никнейм содержит недопустимые символы.' };
  }
  return { ok: true, value };
}

import { createScoreEntry } from '../domain/scoreEntry.js';

/**
 * @param {import('../domain/ports.js').IWritableLeaderboard} repo
 * @returns {(gameId: string, nickname: string, score: number) => void}
 */
export function createSaveScore(repo) {
  return (gameId, nickname, score) => {
    const entry = createScoreEntry(gameId, nickname, score);
    repo.saveScore(entry);
  };
}

/**
 * @param {import('../domain/ports.js').IReadableLeaderboard} repo
 * @returns {(gameId: string, limit?: number) => import('../domain/scoreEntry.js').ScoreEntry[]}
 */
export function createGetLeaderboard(repo) {
  return (gameId, limit = 10) => {
    return repo.getTopScores(gameId, limit);
  };
}

/**
 * @param {import('../domain/ports.js').IReadableLeaderboard} repo
 * @returns {(gameId: string) => number | null}
 */
export function createGetBestScore(repo) {
  return (gameId) => {
    return repo.getBestScore(gameId);
  };
}

import { LS_SCORES_KEY, LS_BEST_KEY, LEADERBOARD_TOP_N } from '../domain/constants.js';

/**
 * @implements {import('../domain/ports.js').IReadableLeaderboard}
 * @implements {import('../domain/ports.js').IWritableLeaderboard}
 */
export class LocalStorageLeaderboardRepository {
  /**
   * @param {number} topN
   */
  constructor(topN = LEADERBOARD_TOP_N) {
    this.topN = topN;
  }

  /** @param {import('../domain/scoreEntry.js').ScoreEntry} entry */
  saveScore(entry) {
    try {
      const key = LS_SCORES_KEY(entry.gameId);
      let list = this._read(key) || [];
      list.push({
        nickname: entry.nickname,
        score: entry.score,
        playedAt: entry.playedAt,
      });
      list.sort((a, b) => b.score - a.score);
      list = list.slice(0, this.topN);
      this._write(key, list);

      // Update best
      const bestKey = LS_BEST_KEY(entry.gameId);
      const currentBest = this._read(bestKey) ?? -Infinity;
      if (entry.score > currentBest) {
        this._write(bestKey, entry.score);
      }
    } catch (e) {
      // Graceful degradation — leaderboard unavailable
    }
  }

  /**
   * @param {string} gameId
   * @param {number} [limit]
   * @returns {import('../domain/scoreEntry.js').ScoreEntry[]}
   */
  getTopScores(gameId, limit = this.topN) {
    try {
      const key = LS_SCORES_KEY(gameId);
      const list = this._read(key) || [];
      return list.slice(0, limit);
    } catch {
      return [];
    }
  }

  /** @param {string} gameId */
  getBestScore(gameId) {
    try {
      const val = this._read(LS_BEST_KEY(gameId));
      return val != null ? Number(val) : null;
    } catch {
      return null;
    }
  }

  _read(key) {
    const raw = localStorage.getItem(key);
    if (raw === null) return null;
    return JSON.parse(raw);
  }

  _write(key, data) {
    localStorage.setItem(key, JSON.stringify(data));
  }
}

/**
 * Unified input manager: keyboard, mouse, touch → actions.
 * Emits named actions consumed by IGame instances.
 */
export class InputManager {
  constructor() {
    /** @type {Set<string>} */
    this._pressed = new Set();
    /** @type {import('./inputManager.js').ActionCallback[]} */
    this._listeners = [];
    this._boundKeyDown = this._onKeyDown.bind(this);
    this._boundKeyUp = this._onKeyUp.bind(this);
    this._boundClick = this._onClick.bind(this);
  }

  /**
   * @param {HTMLElement} element
   */
  attach(element) {
    this._element = element;
    element.addEventListener('keydown', this._boundKeyDown);
    element.addEventListener('keyup', this._boundKeyUp);
    element.addEventListener('click', this._boundClick);
    element.addEventListener('touchstart', this._boundClick, { passive: true });
    // Make element focusable to receive keyboard events
    if (!element.hasAttribute('tabindex')) {
      element.setAttribute('tabindex', '0');
    }
  }

  detach() {
    if (!this._element) return;
    this._element.removeEventListener('keydown', this._boundKeyDown);
    this._element.removeEventListener('keyup', this._boundKeyUp);
    this._element.removeEventListener('click', this._boundClick);
    this._element.removeEventListener('touchstart', this._boundClick);
    this._element = null;
  }

  /** @param {(action: string) => void} cb */
  onAction(cb) {
    this._listeners.push(cb);
  }

  /** @param {(action: string) => void} cb */
  removeActionListener(cb) {
    const idx = this._listeners.indexOf(cb);
    if (idx >= 0) this._listeners.splice(idx, 1);
  }

  isPressed(key) {
    return this._pressed.has(key);
  }

  _emit(action) {
    for (const cb of this._listeners) cb(action);
  }

  _onKeyDown(e) {
    this._pressed.add(e.code);
    if (e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'ArrowDown' ||
        e.code === 'ArrowLeft' || e.code === 'ArrowRight') {
      e.preventDefault();
    }
  }

  _onKeyUp(e) {
    this._pressed.delete(e.code);
    if (e.code === 'Space') {
      this._emit('action');
    }
  }

  _onClick(e) {
    this._emit('action');
  }
}

/**
 * Game loop with fixed timestep accumulator.
 * Calls update(dt) with fixed dt, then render(alpha) for interpolation.
 */
export class RafLoop {
  /**
   * @param {object} opts
   * @param {number} [opts.fixedDt] - fixed timestep in seconds, default 1/60
   * @param {number} [opts.maxAccum] - max accumulated time to avoid spiral, default 0.1
   */
  constructor(opts = {}) {
    this.fixedDt = opts.fixedDt ?? 1 / 60;
    this.maxAccum = opts.maxAccum ?? 0.1;
    /** @type {((dt: number) => void) | null} */
    this._update = null;
    /** @type {((alpha: number) => void) | null} */
    this._render = null;
    this._running = false;
    this._rafId = null;
    this._lastTime = 0;
    this._accum = 0;
    this._boundTick = this._tick.bind(this);
  }

  /**
   * @param {(dt: number) => void} update
   * @param {(alpha: number) => void} render
   */
  start(update, render) {
    this._update = update;
    this._render = render;
    this._running = true;
    this._lastTime = performance.now();
    this._accum = 0;
    this._rafId = requestAnimationFrame(this._boundTick);
  }

  stop() {
    this._running = false;
    if (this._rafId !== null) {
      cancelAnimationFrame(this._rafId);
      this._rafId = null;
    }
    this._update = null;
    this._render = null;
  }

  _tick(now) {
    if (!this._running) return;
    let elapsed = (now - this._lastTime) / 1000;
    this._lastTime = now;
    if (elapsed > this.maxAccum) elapsed = this.maxAccum;
    this._accum += elapsed;

    while (this._accum >= this.fixedDt) {
      if (this._update) this._update(this.fixedDt);
      this._accum -= this.fixedDt;
    }

    const alpha = this._accum / this.fixedDt;
    if (this._render) this._render(alpha);

    this._rafId = requestAnimationFrame(this._boundTick);
  }
}

