{"content": "import { RafLoop } from '../infra/rafLoop.js';

/**
 * Pong vs AI — implements IGame.
 */
export class PongGame {
  /** @param {import('./gameConfigs.js').gameConfigs['pong']} config */
  constructor(config) {
    this.config = config;
    this._gameOverCb = null;
    this._loop = new RafLoop();
    this._canvas = null;
    this._ctx = null;
    this._input = null;

    this._state = 'serve'; // serve | rally | gameover
    this._playerScore = 0;
    this._aiScore = 0;

    this._paddleY = 0;
    this._aiPaddleY = 0;
    this._ballX = 0;
    this._ballY = 0;
    this._ballVx = 0;
    this._ballVy = 0;

    this._w = 0;
    this._h = 0;
    this._pw = 0; // paddle width
    this._ph = 0; // paddle height
  }

  mount(canvas, input) {
    this._canvas = canvas;
    this._ctx = canvas.getContext('2d');
    this._input = input;
    this._resize();
  }

  _resize() {
    if (!this._canvas) return;
    const w = 600;
    const h = Math.min(this._canvas.parentElement?.clientHeight ?? 400, 400);
    this._canvas.width = w;
    this._canvas.height = h;
    this._w = w;
    this._h = h;
    this._pw = this.config.paddleWidth;
    this._ph = this.config.paddleHeight;
    this._paddleY = h / 2 - this._ph / 2;
    this._aiPaddleY = h / 2 - this._ph / 2;
  }

  start() {
    this._playerScore = 0;
    this._aiScore = 0;
    this._state = 'serve';
    this._resetBall();
    this._input.onAction(this._onAction);
    if (this._canvas) {
      this._boundKeyDown = (e) => this._handleKey(e);
      this._canvas.addEventListener('keydown', this._boundKeyDown);
    }
    this._loop.start((dt) => this._update(dt), () => this._render());
  }

  pause() { this._loop.stop(); }

  resume() {
    if (this._state === 'gameover') return;
    this._loop.start((dt) => this._update(dt), () => this._render());
  }

  dispose() {
    this._loop.stop();
    if (this._input) this._input.removeActionListener(this._onAction);
    if (this._canvas) this._canvas.removeEventListener('keydown', this._boundKeyDown);
    this._canvas = null;
    this._ctx = null;
  }

  onGameOver(cb) { this._gameOverCb = cb; }

  _onAction = () => {
    if (this._state === 'serve') {
      this._state = 'rally';
      // Launch ball toward a random direction away from player
      const angle = (Math.random() * 0.8 + 0.2) * Math.PI; // 36°–144°
      const dir = Math.random() > 0.5 ? 1 : -1;
      this._ballVx = Math.cos(angle) * this.config.ballSpeed * dir;
      this._ballVy = Math.sin(angle) * this.config.ballSpeed * (dir > 0 ? 1 : -1);
    }
  };

  _handleKey(e) {
    if (e.code === 'ArrowUp' || e.code === 'ArrowDown') e.preventDefault();
  }

  _resetBall() {
    this._ballX = this._w / 2;
    this._ballY = this._h / 2;
    this._ballVx = 0;
    this._ballVy = 0;
    this._state = 'serve';
  }

  _update(dt) {
    if (this._state === 'gameover') return;

    // Player paddle movement
    const ps = this.config.paddleSpeed;
    if (this._input && this._input.isPressed) {
      // Use raw keyboard tracking via presses
    }
    // We track keys from input manager pressed set
    if (this._input) {
      if (this._input.isPressed('ArrowUp')) {
        this._paddleY = Math.max(0, this._paddleY - ps * dt);
      }
      if (this._input.isPressed('ArrowDown')) {
        this._paddleY = Math.min(this._h - this._ph, this._paddleY + ps * dt);
      }
    }

    if (this._state !== 'rally') return;

    // AI paddle
    const aiTarget = this._ballY - this._ph / 2;
    const diff = aiTarget - this._aiPaddleY;
    const aiSpeed = Math.min(Math.abs(diff) / dt * this.config.aiReactionSpeed, this.config.aiMaxSpeed);
    if (Math.abs(diff) > 4) {
      this._aiPaddleY += Math.sign(diff) * Math.min(aiSpeed * dt, Math.abs(diff));
    }
    this._aiPaddleY = Math.max(0, Math.min(this._h - this._ph, this._aiPaddleY));

    // Ball movement
    this._ballX += this._ballVx * dt;
    this._ballY += this._ballVy * dt;

    // Top/bottom bounce
    const bs = this.config.ballSize;
    if (this._ballY - bs < 0) { this._ballY = bs; this._ballVy = -this._ballVy; }
    if (this._ballY + bs > this._h) { this._ballY = this._h - bs; this._ballVy = -this._ballVy; }

    // Left wall → AI scores
    if (this._ballX - bs < 0) {
      this._aiScore++;
      if (this._aiScore >= this.config.winScore) {
        this._state = 'gameover';
        this._loop.stop();
        if (this._gameOverCb) this._gameOverCb(this._playerScore);
        return;
      }
      this._resetBall();
      return;
    }

    // Right wall → player scores
    if (this._ballX + bs > this._w) {
      this._playerScore++;
      if (this._playerScore >= this.config.winScore) {
        this._state = 'gameover';
        this._loop.stop();
        if (this._gameOverCb) this._gameOverCb(this._playerScore);
        return;
      }
      this._resetBall();
      return;
    }

    // Paddle collision — player (left)
    if (this._ballVx < 0 &&
        this._ballX - bs < this._pw &&
        this._ballY > this._paddleY &&
        this._ballY < this._paddleY + this._ph) {
      this._ballX = this._pw + bs;
      const hitPos = (this._ballY - (this._paddleY + this._ph / 2)) / (this._ph / 2);
      const angle = hitPos * Math.PI / 4; // -45° to +45°
      this._ballVx = Math.cos(angle) * this.config.ballSpeed;
      this._ballVy = Math.sin(angle) * this.config.ballSpeed;
