      this._boundMouse = (e) => {
        const rect = this._canvas.getBoundingClientRect();
        this._mouseX = e.clientX - rect.left;
        this._mouseY = e.clientY - rect.top;
      };
      this._canvas.addEventListener('mousemove', this._boundMouse);
      this._canvas.addEventListener('click', () => this._shootAction());
    }
    this._loop.start((dt) => this._update(dt), () => this._render());
  }

  pause() { this._loop.stop(); }

  resume() {
    if (this._state === 'gameover') return;
    this._loop.start((dt) => this._update(dt), () => this._render());
  }

  dispose() {
    this._loop.stop();
    if (this._input) this._input.removeActionListener(this._shootAction);
    if (this._canvas && this._boundMouse) {
      this._canvas.removeEventListener('mousemove', this._boundMouse);
      this._canvas.removeEventListener('click', this._shootAction);
    }
    this._canvas = null;
    this._ctx = null;
  }

  onGameOver(cb) { this._gameOverCb = cb; }

  _shootAction = () => {
    if (this._state === 'gameover') return;
    if (this._shootCooldown > 0) return;
    this._shootCooldown = this.config.shootCooldown;

    // Bullet toward mouse (or angle from movement)
    let angle;
    if (this._mouseX > 0 && this._mouseY > 0 &&
        this._mouseX < this._w && this._mouseY < this._h) {
      angle = Math.atan2(this._mouseY - this._player.y, this._mouseX - this._player.x);
    } else {
      // Fallback: shoot right
      angle = 0;
    }

    this._bullets.push({
      x: this._player.x + Math.cos(angle) * (this._player.size + 4),
      y: this._player.y + Math.sin(angle) * (this._player.size + 4),
      vx: Math.cos(angle) * this.config.bulletSpeed,
      vy: Math.sin(angle) * this.config.bulletSpeed,
      radius: this.config.bulletRadius,
      life: 1.5,
    });
  };

  _startNextWave() {
    this._wave++;
    this._enemiesThisWave = Math.floor(
      this.config.baseEnemiesPerWave * Math.pow(this.config.waveMultiplier, this._wave - 1)
    );
    this._enemiesSpawned = 0;
    this._spawnTimer = 0;
    this._state = 'spawning';
  }

  _spawnEnemy() {
    // Spawn at random edge
    const margin = this.config.enemySpawnRadius;
    let x, y;
    const edge = Math.floor(Math.random() * 4);
    switch (edge) {
      case 0: x = Math.random() * this._w; y = -margin; break; // top
      case 1: x = this._w + margin; y = Math.random() * this._h; break; // right
      case 2: x = Math.random() * this._w; y = this._h + margin; break; // bottom
      case 3: x = -margin; y = Math.random() * this._h; break; // left
    }
    this._enemies.push({
      x, y,
      size: this.config.enemySize,
      hp: 1,
      speed: this.config.enemySpeed + this._wave * 5,
    });
    this._enemiesSpawned++;
  }

  _update(dt) {
    if (this._state === 'gameover' || !this._player) return;

    // Player movement (WASD / arrows)
    let dx = 0, dy = 0;
    if (this._input) {
      if (this._input.isPressed('KeyW') || this._input.isPressed('ArrowUp')) dy = -1;
      if (this._input.isPressed('KeyS') || this._input.isPressed('ArrowDown')) dy = 1;
      if (this._input.isPressed('KeyA') || this._input.isPressed('ArrowLeft')) dx = -1;
      if (this._input.isPressed('KeyD') || this._input.isPressed('ArrowRight')) dx = 1;
    }
    if (dx !== 0 || dy !== 0) {
      const len = Math.sqrt(dx * dx + dy * dy);
      this._player.x += (dx / len) * this.config.playerSpeed * dt;
      this._player.y += (dy / len) * this.config.playerSpeed * dt;
    }
    this._player.x = Math.max(this._player.size, Math.min(this._w - this._player.size, this._player.x));
    this._player.y = Math.max(this._player.size, Math.min(this._h - this._player.size, this._player.y));

    // Shoot cooldown
    if (this._shootCooldown > 0) this._shootCooldown -= dt;

    // Spawn enemies
    if (this._state === 'spawning') {
      this._spawnTimer += dt;
      if (this._spawnTimer >= this.config.spawnInterval && this._enemiesSpawned < this._enemiesThisWave) {
        this._spawnTimer = 0;
        this._spawnEnemy();
      }
      if (this._enemiesSpawned >= this._enemiesThisWave) {
        this._state = 'fighting';
      }
    }

    // Move enemies toward player
    for (const e of this._enemies) {
      const dx2 = this._player.x - e.x;
      const dy2 = this._player.y - e.y;
      const dist = Math.sqrt(dx2 * dx2 + dy2 * dy2);
      if (dist > 1) {
        e.x += (dx2 / dist) * e.speed * dt;
        e.y += (dy2 / dist) * e.speed * dt;
      }
    }

    // Move bullets
    for (let i = this._bullets.length - 1; i >= 0; i--) {
      const b = this._bullets[i];
      b.x += b.vx * dt;
      b.y += b.vy * dt;
      b.life -= dt;
      if (b.life <= 0 || b.x < -10 || b.x > this._w + 10 || b.y < -10 || b.y > this._h + 10) {
        this._bullets.splice(i, 1);
      }
    }

    // Bullet vs enemy collisions
    for (let i = this._bullets.length - 1; i >= 0; i--) {
      const b = this._bullets[i];
      let hit = false;
      for (let j = this._enemies.length - 1; j >= 0; j--) {
        const e = this._enemies[j];
        const dx2 = b.x - e.x;
        const dy2 = b.y - e.y;
        if (dx2 * dx2 + dy2 * dy2 < (b.radius + e.size) * (b.radius + e.size)) {
          this._enemies.splice(j, 1);
          this._score += 10;
          hit = true;
          break;
        }
      }
      if (hit) this._bullets.splice(i, 1);
    }

    // Enemy vs player collision
    const ps = this._player.size;
    for (let i = this._enemies.length - 1; i >= 0; i--) {
      const e = this._enemies[i];
      const dx2 = this._player.x - e.x;
      const dy2 = this._player.y - e.y;
      if (dx2 * dx2 + dy2 * dy2 < (ps + e.size) * (ps + e.size)) {
        this._player.hp -= 10;
        this._enemies.splice(i, 1);
        if (this._player.hp <= 0) {
          this._state = 'gameover';
          this._loop.stop();
          if (this._gameOverCb) this._gameOverCb(Math.floor(this._score));
          return;
        }
      }
    }

    // Wave cleared → next wave + survival bonus
    if (this._state === 'fighting' && this._enemies.length === 0) {
      this._score += this._wave * 5; // survival bonus
      this._startNextWave();
    }
  }

  _render() {
    const ctx = this._ctx;
    if (!ctx) return;

    // Background
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, this._w, this._h);

    // Grid
    ctx.strokeStyle = '#222';
    ctx.lineWidth = 1;
    for (let x = 0; x < this._w; x += 40) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, this._h); ctx.stroke();
    }
    for (let y = 0; y < this._h; y += 40) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(this._w, y); ctx.stroke();
    }

    // Bullets
    ctx.fillStyle = '#f1c40f';
    for (const b of this._bullets) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Enemies
    ctx.fillStyle = '#e74c3c';
    for (const e of this._enemies) {
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.size, 0, Math.PI * 2);
      ctx.fill();
      // Eyes
      ctx.fillStyle = '#000';
      ctx.beginPath();
      ctx.arc(e.x - 4, e.y - 3, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(e.x + 4, e.y - 3, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#e74c3c';
    }

    // Player
    if (this._player) {
      ctx.fillStyle = '#3498db';
      ctx.beginPath();
      ctx.arc(this._player.x, this._player.y, this._player.size, 0, Math.PI * 2);
      ctx.fill();

      // HP bar
      const barW = 40;
      const barH = 4;
      const hpPct = this._player.hp / this.config.playerMaxHp;
      ctx.fillStyle = '#333';
      ctx.fillRect(this._player.x - barW / 2, this._player.y - this._player.size - 10, barW, barH);
      ctx.fillStyle = hpPct > 0.3 ? '#2ecc71' : '#e74c3c';
      ctx.fillRect(this._player.x - barW / 2, this._player.y - this._player.size - 10, barW * hpPct, barH);
    }

    // HUD
    ctx.fillStyle = 'rgba(255,255,255,0.9)';
    ctx.font = '16px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${this._score}`, 8, 20);
    ctx.fillText(`Wave: ${this._wave}`, 8, 38);
    if (this._state === 'spawning') {
      const remain = this._enemiesThisWave - this._enemiesSpawned;
      ctx.fillText(`Enemies incoming: ${remain}`, 8, 56);
    } else {
      ctx.fillText(`Enemies: ${this._enemies.length}`, 8, 56);
    }
  }
}

