    });
    actions.appendChild(resetBtn);

    hub.appendChild(actions);
    this._root.appendChild(hub);
  }

  _launchGame(gameId) {
    this._root.innerHTML = '';
    this._gameOverOverlay.remove();

    const screen = document.createElement('div');
    screen.className = 'game-screen';
    screen.appendChild(this._canvas);
    this._root.appendChild(screen);

    // Ensure canvas is in DOM before mounting
    requestAnimationFrame(() => {
      const game = createGame(gameId);
      this._currentGame = game;

      this._input.attach(this._canvas);
      game.mount(this._canvas, this._input);

      game.onGameOver((score) => {
        this._showGameOver(gameId, score);
      });

      game.start();
    });
  }

  _showGameOver(gameId, score) {
    const best = this._getBestScore(gameId);
    this._gameOverOverlay.show({
      score,
      best,
      onSubmit: (nickname) => {
        const result = validateNickname(nickname);
        if (!result.ok) {
          return result.error;
        }
        this._saveScore(gameId, result.value, score);
        return null;
      },
      onRetry: () => {
        if (this._currentGame) {
          this._currentGame.dispose();
        }
        this._launchGame(gameId);
      },
      onHub: () => {
        if (this._currentGame) {
          this._currentGame.dispose();
        }
        this._showHub();
      },
      onLeaderboard: () => {
        this._showLeaderboard(gameId);
      },
    });
    this._root.appendChild(this._gameOverOverlay.getElement());
  }

  _showLeaderboard(highlightGameId) {
    this._leaderboardView.show(highlightGameId);
    this._root.appendChild(this._leaderboardView.getElement());
  }
}

/**
 * Game Over overlay component.
 */
export class GameOverOverlay {
  constructor() {
    this._el = document.createElement('div');
    this._el.className = 'game-over-overlay';
    this._el.innerHTML = `
      <div class="game-over-box">
        <h2>Игра окончена</h2>
        <div class="final-score"></div>
        <div class="best-score"></div>
        <div class="message"></div>
        <div class="nickname-row">
          <input type="text" placeholder="Введи никнейм (необязательно)" maxlength="16">
          <button class="btn btn-primary btn-small">Отправить</button>
        </div>
        <div class="actions">
          <button class="btn retry-btn">🔄 Заново</button>
          <button class="btn hub-btn">🏠 К списку игр</button>
          <button class="btn leaderboard-btn">📊 Таблица лидеров</button>
        </div>
      </div>
    `;

    this._messageEl = this._el.querySelector('.message');
    this._scoreEl = this._el.querySelector('.final-score');
    this._bestEl = this._el.querySelector('.best-score');
    this._input = this._el.querySelector('input');
    this._submitBtn = this._el.querySelector('.nickname-row .btn');
    this._retryBtn = this._el.querySelector('.retry-btn');
    this._hubBtn = this._el.querySelector('.hub-btn');
    this._lbBtn = this._el.querySelector('.leaderboard-btn');
  }

  show({ score, best, onSubmit, onRetry, onHub, onLeaderboard }) {
    this._scoreEl.textContent = score;
    this._bestEl.textContent = best !== null ? `🏆 Лучший: ${best}` : '';
    this._messageEl.textContent = '';
    this._messageEl.className = 'message';
    this._input.value = '';

    // Remove old listeners by cloning
    const newSubmit = this._submitBtn.cloneNode(true);
    this._submitBtn.replaceWith(newSubmit);
    this._submitBtn = newSubmit;

    const newInput = this._input.cloneNode(true);
    this._input.replaceWith(newInput);
    this._input = newInput;

    this._submitBtn.addEventListener('click', () => {
      const error = onSubmit(this._input.value);
      if (error) {
        this._messageEl.textContent = error;
        this._messageEl.className = 'message error';
      } else {
        this._messageEl.textContent = '✅ Сохранено!';
        this._messageEl.className = 'message success';
        this._input.disabled = true;
        this._submitBtn.disabled = true;
      }
    });

    this._input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') this._submitBtn.click();
    });

    this._retryBtn.onclick = onRetry;
    this._hubBtn.onclick = onHub;
    this._lbBtn.onclick = onLeaderboard;
  }

  getElement() {
    return this._el;
  }

  remove() {
    this._el.remove();
  }
}

import { gamesMeta } from '../games/gameConfigs.js';

/**
 * Leaderboard view — shows top scores for a selected game.
 */
export class LeaderboardView {
  /**
   * @param {(gameId: string, limit?: number) => import('../domain/scoreEntry.js').ScoreEntry[]} getLeaderboard
   */
  constructor(getLeaderboard) {
    this._getLeaderboard = getLeaderboard;
    this._el = document.createElement('div');
    this._el.className = 'leaderboard-view';
    this._el.innerHTML = `
      <div class="leaderboard-box">
        <h2>📊 Таблица лидеров</h2>
        <div class="game-selector"></div>
        <div class="content"></div>
        <button class="btn close-btn">Закрыть</button>
      </div>
    `;
    this._content = this._el.querySelector('.content');
    this._gameSelector = this._el.querySelector('.game-selector');
    this._el.querySelector('.close-btn').addEventListener('click', () => this._el.remove());
  }

  show(highlightGameId) {
    // Build game selector buttons
    this._gameSelector.innerHTML = '';
    for (const meta of gamesMeta) {
      const btn = document.createElement('button');
      btn.className = 'btn btn-small' + (meta.id === highlightGameId ? ' btn-primary' : '');
      btn.textContent = meta.icon + ' ' + meta.title;
      btn.addEventListener('click', () => {
        this._renderLeaderboard(meta.id);
        // Highlight active
        this._gameSelector.querySelectorAll('.btn').forEach(b => b.classList.remove('btn-primary'));
        btn.classList.add('btn-primary');
      });
      this._gameSelector.appendChild(btn);
    }

    // Show for highlighted game, or first
    const target = highlightGameId || gamesMeta[0]?.id;
    if (target) {
      // Highlight matching button
      const btns = this._gameSelector.querySelectorAll('.btn');
      btns.forEach(b => {
        if (b.textContent.includes(gamesMeta.find(m => m.id === target)?.title || '')) {
          b.classList.add('btn-primary');
        }
      });
      this._renderLeaderboard(target);
    }
  }

  _renderLeaderboard(gameId) {
    const meta = gamesMeta.find(m => m.id === gameId);
    const entries = this._getLeaderboard(gameId);
    const escapedTitle = meta ? this._escape(meta.title) : gameId;

    if (entries.length === 0) {
      this._content.innerHTML = `<div class="empty">Нет записей для «${escapedTitle}».</div>`;
      return;
    }

    let html = `<table><thead><tr><th>#</th><th>Никнейм</th><th>Счёт</th><th>Дата</th></tr></thead><tbody>`;
    for (let i = 0; i < entries.length; i++) {
      const e = entries[i];
      const date = new Date(e.playedAt).toLocaleDateString('ru-RU');
      html += `<tr>
        <td class="rank">${i + 1}</td>
        <td class="nickname">${this._escape(e.nickname)}</td>
        <td class="score">${e.score}</td>
        <td class="date">${date}</td>
      </tr>`;
    }
    html += '</tbody></table>';
    this._content.innerHTML = html;
  }

  _escape(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  getElement() {
    return this._el;
  }
}

